import json,re
from pathlib import Path
D=Path(__file__).parent
v=json.loads((D/'baseline-v.json').read_text())
by={s['id']:s for s in v['sections']}
ledger=[]
def change(sid,old,new,why):
 s=by[sid]; assert old in s['html'],(sid,old)
 s['html']=s['html'].replace(old,new)
 ledger.append({'section':sid,'before':old,'after':new,'reason':why,'destination':sid})
def fold(sid,body,title,suffix):
 return '<details class="v49-detail" id="v49-'+suffix+'"><summary>'+title+'</summary><div class="v49-detail-body">'+body+'</div></details>'
v['intro']='<p>主驾说<b>“带我去昨天那家游泳馆”</b>，停了一下，又补充<b>“附近的餐厅”</b>。他最终要找的是餐厅，游泳馆用来限定位置。系统如果只接住前半句，就可能把目的地选错；如果一直等到整句话结束才开始计算，用户又会觉得慢。</p><p>本章跟着这次请求，讲清声音怎样变成可处理的请求，再交给 DT（Director，也叫 Planner，负责理解需求、规划和调用工具）。正文沿业务路径讲，训练方法、接口参数和历史评测放在对应段落的展开项中。图保留原样；涉及车型差异或图中时序简写的地方，在图下说明适用条件。</p>'
change('v39-map','先把整条路看一遍。下面这张图就是这一章的“地图”，后面每一节都是沿着它往下走。','主例按“接住完整的话、确认要不要接、决定怎样办”往前走。图中的 12 个编号标出业务环节，其中有几条支路会同时运行。','避免把编号当成严格串行')
change('v39-map','左列是车上做的事，右列是云端做的事，按圆圈里的编号 1–12 从上往下读。箭头每跨一次列，就是车和云之间传了一次东西，线上的小字是传了什么。','先看左侧收音，把声音沿箭头送给识别服务；服务持续返回过程文字。与此同时，判停模块观察同一段声音里的停顿。若豆包正在播报，流式拒识还会利用过程文字判断要不要停播。这三项判断可以交错发生，不能理解为识别全部做完才开始判停。','解释并行路径')
change('v39-map','先只记住一个分工：<b>车上负责“听”和“动手”</b>，收音、计停顿、播报、执行；<b>云端负责“听懂”和“想”</b>，识别文字、判断是不是在找豆包、找背景、做决策。','顺着正式提交的箭头，云端拿到定稿文字，判断是否接话，并为 DT 准备上下文。车上的本地链路拿自己的识别结果计算候选指令，它不必等云端全部完成。仲裁决定采用哪一路：固定规则可先执行，云端超时也可能直接采用有效的本地结果。因此，图里画在 DT 后面的仲裁，不能读成所有分支都必须等 DT 返回。','澄清本地启动和仲裁时机')
change('v39-map','</div><p>这 12 步可以分成五段，后面就按这五段讲：</p>','<p>图的左右列表示部署位置，具体车型仍有差异。例如上汽资料把流式拒识放到云端服务器运行，赛力斯资料描述车上运行；端侧 FC 也能理解指令。模型的职责与运行位置要分别看，不能归纳成“车上只执行、云端才理解”。这些差异在第二、四段就地说明。</p></div><p>正文分成五段，插话这一段只在豆包正在播报等前提满足时发生：</p>','保留图并在图下说明疑点')
by['v39-map']['title']='先看整条链路：12 个环节怎样配合'
change('v39-map','四、是不是找豆包，两路同时开跑','四、判断是否接话，保留本地与云端结果','不把支路起点绑定到章节顺序')
change('v39-map','一个确定要办的请求（车上的结果先放着）','云端是否接话的判断；本地候选结果及其适用条件','明确多支路输出')
